	"hadiths": [
		{
			"hadithnumber": 5125,
			"arabicnumber": 5125,
			"text": "ہم سے مسدد نے بیان کیا، کہا ہم سے حماد بن زید نے بیان کیا، ان سے ہشام بن عروہ نے، ان سے ان کے والد عروہ بن زبیر نے اور ان سے عائشہ رضی اللہ عنہا نے بیان کیا کہ مجھ سے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا کہ ( نکاح سے پہلے ) میں نے تمہیں خواب میں دیکھا کہ ایک فرشتہ ( جبرائیل علیہ السلام ) ریشم کے ایک ٹکڑے میں تمہیں لپیٹ کر لے آیا ہے اور مجھ سے کہہ رہا ہے کہ یہ تمہاری بیوی ہے۔ میں نے اس کے چہرے سے کپڑا ہٹایا تو وہ تم تھیں۔ میں نے کہا کہ اگر یہ خواب اللہ کی طرف سے ہے تو وہ اسے خود ہی پورا کر دے گا۔",
			"grades": [],
			"reference": {
				"book": 67,
				"hadith": 61
			}
		}
	]
}

